<span class="line"><span style="color:#ABB2BF;">    weight </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> np.random.</span><span style="color:#61AFEF;">randn</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">32</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">16</span><span style="color:#ABB2BF;">)</span></span>
